public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    // Precompute adjacency matrix
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            can[i][j] = r * r == sum;
        }
    }
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int fullMask = (1 << n) - 1;
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            long key = ((long) mask << 32) | (last + 1);
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            if (mask == fullMask) return 1;
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (last != -1 && !can[last][i]) continue;
                // skip duplicates
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                count += applyAsInt(mask | (1 << i), i);
            }
            memo.put(key, count);
            return count;
        }
    };
    return dfs.applyAsInt(0, -1);
}

